    public override Dictionary<string, object> parseTransaction(object transaction, object currency = null)
    {
        //
        // fetchDeposits
        //     [
        //         {
        //             "createdAt": "2025-07-23T13:55:54.267",
        //             "fiatAmount": null,
        //             "fiatCurrency": null,
        //             "fromAddress": "0x2e3ab3e88a7dbdc763aadf5b28c18fb085af420a",
        //             "id": 6695353,
        //             "institutionBic": null,
        //             "platformMemo": null,
        //             "quantity": "120",
        //             "source": "ethereum",
        //             "status": "confirmed",
        //             "symbol": "USDC",
        //             "toAddress": "0xfBe7CbfCde93c8a4204a4be6B56732Eb32690170",
        //             "transactionHash": "0x58edaac415398d617b34c6673fffcaf0024990d5700565030119db5cbf3765d1"
        //         }
        //     ]
        //
        // withdraw
        //     {
        //         "accountIdentifier": null,
        //         "bankIdentifier": null,
        //         "bankName": null,
        //         "blockchain": "Ethereum",
        //         "clientId": null,
        //         "createdAt": "2025-08-13T19:27:13.817",
        //         "fee": "3",
        //         "fiatFee": null,
        //         "fiatState": null,
        //         "fiatSymbol": null,
        //         "id": 5479929,
        //         "identifier": null,
        //         "isInternal": false,
        //         "providerId": null,
        //         "quantity": "10",
        //         "status": "pending",
        //         "subaccountId": null,
        //         "symbol": "USDC",
        //         "toAddress": "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749",
        //         "transactionHash": null,
        //         "triggerAt": null
        //     }
        //
        // fetchWithdrawals
        //     [
        //         {
        //             "accountIdentifier": null,
        //             "bankIdentifier": null,
        //             "bankName": null,
        //             "blockchain": "Ethereum",
        //             "clientId": null,
        //             "createdAt": "2025-08-13T19:27:13.817",
        //             "fee": "3",
        //             "fiatFee": null,
        //             "fiatState": null,
        //             "fiatSymbol": null,
        //             "id": 5479929,
        //             "identifier": null,
        //             "isInternal": false,
        //             "providerId": null,
        //             "quantity": "10",
        //             "status": "confirmed",
        //             "subaccountId": null,
        //             "symbol": "USDC",
        //             "toAddress": "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749",
        //             "transactionHash": "0x658b6d082af4afa0d3cf85caf344ff7c19d980117726bf193b00d8850f8746a1",
        //             "triggerAt": null
        //         }
        //     ]
        //
        string? status = this.parseTransactionStatus(this.safeString(transaction, "status"));
        string? id = this.safeString(transaction, "id");
        string? txid = this.safeString(transaction, "transactionHash");
        string? coin = this.safeString(transaction, "symbol");
        string? code = this.safeCurrencyCode(coin, currency);
        Int64? timestamp = this.parse8601(this.safeString(transaction, "createdAt"));
        double? amount = this.safeNumber(transaction, "quantity");
        string? networkId = this.safeStringLower2(transaction, "source", "blockchain");
        string? network = this.networkIdToCode(networkId, code);
        string? addressTo = this.safeString(transaction, "toAddress");
        string? addressFrom = this.safeString(transaction, "fromAddress");
        string? tag = this.safeString(transaction, "platformMemo");
        double? feeCost = this.safeNumber(transaction, "fee");
        bool? intern = this.safeBool(transaction, "isInternal", false);
        Dictionary<string, object> fee = null;
        if ((feeCost != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", code },
            };
        }
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", id },
            { "txid", txid },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "network", network },
            { "address", null },
            { "addressTo", addressTo },
            { "addressFrom", addressFrom },
            { "tag", tag },
            { "tagTo", null },
            { "tagFrom", null },
            { "type", null },
            { "amount", amount },
            { "currency", code },
            { "status", status },
            { "updated", null },
            { "internal", intern },
            { "comment", null },
            { "fee", fee },
        };
    }

    public virtual string? parseTransactionStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "cancelled", "cancelled" },
            { "confirmed", "ok" },
            { "declined", "declined" },
            { "expired", "expired" },
            { "initiated", "initiated" },
            { "pending", "pending" },
            { "refunded", "refunded" },
            { "information required", "pending" },
        };
        return this.safeString(statuses, status, status);
    }

