    public override Dictionary<string, object> parsePosition(object position, IDictionary<string, object> market = null)
    {
        //
        // fetchPositions
        //     {
        //         "breakEvenPrice": "3831.3630555555555555555555556",
        //         "cumulativeFundingPayment": "-0.009218",
        //         "cumulativeInterest": "0",
        //         "entryPrice": "3826.8888888888888888888888889",
        //         "estLiquidationPrice": "0",
        //         "imf": "0.02",
        //         "imfFunction": {
        //             "base": "0.02",
        //             "factor": "0.0000935",
        //             "type": "sqrt"
        //         },
        //         "markPrice": "3787.46813304",
        //         "mmf": "0.0125",
        //         "mmfFunction": {
        //             "base": "0.0125",
        //             "factor": "0.0000561",
        //             "type": "sqrt"
        //         },
        //         "netCost": "13.7768",
        //         "netExposureNotional": "13.634885278944",
        //         "netExposureQuantity": "0.0036",
        //         "netQuantity": "0.0036",
        //         "pnlRealized": "0",
        //         "pnlUnrealized": "-0.141914",
        //         "positionId": "4238420454",
        //         "subaccountId": null,
        //         "symbol": "ETH_USDC_PERP",
        //         "userId":1813870
        //     }
        //
        string? id = this.safeString(position, "positionId");
        string? marketId = this.safeString(position, "symbol");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        string? symbol = ((string)(marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null));
        string? entryPrice = this.safeString(position, "entryPrice");
        string? markPrice = this.safeString(position, "markPrice");
        string? netCost = this.safeString(position, "netCost");
        bool? hedged = false;
        string? side = "long";
        if (Precise.stringLt(netCost, "0"))
        {
            side = "short";
        }
        if ((netCost == null))
        {
            hedged = null;
            side = null;
        }
        string? unrealizedPnl = this.safeString(position, "pnlUnrealized");
        string? realizedPnl = this.safeString(position, "pnlRealized");
        string? liquidationPrice = this.safeString(position, "estLiquidationPrice");
        return this.safePosition(new Dictionary<string, object>() {
            { "info", position },
            { "id", id },
            { "symbol", symbol },
            { "timestamp", this.parse8601(this.safeString(position, "timestamp")) },
            { "datetime", this.iso8601(this.parse8601(this.safeString(position, "timestamp"))) },
            { "lastUpdateTimestamp", null },
            { "hedged", hedged },
            { "side", side },
            { "contracts", this.safeString(position, "netExposureQuantity") },
            { "contractSize", null },
            { "entryPrice", entryPrice },
            { "markPrice", markPrice },
            { "lastPrice", null },
            { "notional", Precise.stringAbs(netCost) },
            { "leverage", null },
            { "collateral", null },
            { "initialMargin", null },
            { "initialMarginPercentage", this.safeString(position, "imf") },
            { "maintenanceMargin", null },
            { "maintenanceMarginPercentage", this.safeString(position, "mmf") },
            { "realizedPnl", realizedPnl },
            { "unrealizedPnl", unrealizedPnl },
            { "liquidationPrice", liquidationPrice },
            { "marginMode", null },
            { "marginRatio", null },
            { "percentage", null },
            { "stopLossPrice", null },
            { "takeProfitPrice", null },
        });
    }

